class Solution {
public:
    int reachableNodes(vector<vector<int>>& edges, int maxMoves, int n) {
        vector<vector<pair<int, int>>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }
        vector<int> dist(n, -1);
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        pq.push({0, 0});
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (dist[u] != -1) continue;
            dist[u] = d;
            for (auto& [v, w] : adj[u]) {
                if (dist[v] == -1 && d + w + 1 <= maxMoves) {
                    pq.push({d + w + 1, v});
                }
            }
        }
        int ans = 0;
        for (int i = 0; i < n; i++) if (dist[i] != -1) ans++;
        for (auto& e : edges) {
            int u = e[0], v = e[1], w = e[2];
            int a = (dist[u] != -1) ? max(0, maxMoves - dist[u]) : 0;
            int b = (dist[v] != -1) ? max(0, maxMoves - dist[v]) : 0;
            ans += min(w, a + b);
        }
        return ans;
    }
};

class Solution {
    public int reachableNodes(int[][] edges, int maxMoves, int n) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], e[2]});
            adj[e[1]].add(new int[]{e[0], e[2]});
        }
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        pq.offer(new int[]{0, 0});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], u = top[1];
            if (dist[u] != -1) continue;
            dist[u] = d;
            for (int[] nxt : adj[u]) {
                int v = nxt[0], w = nxt[1];
                if (dist[v] == -1 && d + w + 1 <= maxMoves) {
                    pq.offer(new int[]{d + w + 1, v});
                }
            }
        }
        int ans = 0;
        for (int i = 0; i < n; i++) if (dist[i] != -1) ans++;
        for (int[] e : edges) {
            int u = e[0], v = e[1], w = e[2];
            int a = (dist[u] != -1) ? Math.max(0, maxMoves - dist[u]) : 0;
            int b = (dist[v] != -1) ? Math.max(0, maxMoves - dist[v]) : 0;
            ans += Math.min(w, a + b);
        }
        return ans;
    }
}

var reachableNodes = function(edges, maxMoves, n) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const dist = new Array(n).fill(-1);
    const pq = [[0, 0]];
    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, u] = pq.shift();
        if (dist[u] !== -1) continue;
        dist[u] = d;
        for (const [v, w] of adj[u]) {
            if (dist[v] === -1 && d + w + 1 <= maxMoves) {
                pq.push([d + w + 1, v]);
            }
        }
    }
    let ans = 0;
    for (let i = 0; i < n; i++) if (dist[i] !== -1) ans++;
    for (const [u, v, w] of edges) {
        const a = dist[u] !== -1 ? Math.max(0, maxMoves - dist[u]) : 0;
        const b = dist[v] !== -1 ? Math.max(0, maxMoves - dist[v]) : 0;
        ans += Math.min(w, a + b);
    }
    return ans;
};
